INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65719639', 65719639, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA TALU01', 'Pengadaan peralatan fasilitas perkantoran berupa Meja dan Kursi Hakim', 'Barang', 'E-Purchasing', 'Sumatera Barat, Pasaman Barat (Kab.)', 28000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Belanja Modal Peralatan dan Mesin untuk meubelair kantor berupa kursi, meja, dan lemari arsip sesuai spesifikasi teknis.', 'Pengadaan Meubelair Kantor (e-Purchasing) 1. Ruang Lingkup Pengadaan meubelair kantor melalui e-Katalog Nasional berupa kursi, meja, dan lemari arsip untuk menunjang operasional perkantoran. 2. Spesifikasi Umum Metode pengadaan : e-Purchasing (e-Katalog) Kondisi barang : Baru Kualitas : Standar perkantoran Produk tersedia dan aktif di e-Katalog Tidak dibatasi merek tertentu 3. Spesifikasi Teknis Minimum a. Kursi Kantor Jenis : Kursi kerja/kursi kantor Material rangka : Logam/kayu atau setara Dudukan & sandaran : Empuk dan ergonomis Penggunaan : Kerja harian perkantoran b. Meja Kantor Jenis : Meja kerja kantor Material : Kayu olahan/logam atau setara Konstruksi : Kokoh dan stabil Penggunaan : Kerja administrasi c. Lemari Arsip Jenis : Lemari arsip kantor Material : Logam/kayu atau setara Sistem : Pintu ayun/geser, dapat dikunci Fungsi : Penyimpanan dokumen 4. Pengiriman Pengiriman ke lokasi satuan kerja Termasuk bongkar dan penempatan Barang diterima dalam kondisi siap pakai 5. Garansi Garansi produk mengikuti ketentuan penyedia dalam e-Katalog Minimal sesuai standar pabrikan 6. Waktu Pelaksanaan Pengiriman paling lambat 14 (empat belas) hari kalender sejak pemesanan pada e-Katalog.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2327654);
